#!/bin/bash
# Rebuilds website.html from the generated partials.
#
# The body is generated by _gen_website.py from the twenty-section
# specification, so every numbered sub-item is present by construction and
# the figures stay consistent across sections.
set -e
cd "$(dirname "$0")"

python3 _gen_website.py
cat _website.css _website2.css > _website-build.css
python3 _compose.py _wm2head.html website _website-build.css

{
  cat _wm2head.html
  cat _wm2body.html
  cat _wm2js.js
  printf '</body>\n</html>\n'
} > website.html

python3 - <<'PY'
import pathlib
p = pathlib.Path('website.html')
s = p.read_text()
s = s.replace('<title>Module — GOLDEN FINANCIAL SERVICES</title>',
              '<title>Website Management &amp; Connections — GOLDEN FINANCIAL SERVICES</title>')
p.write_text(s)
print('built website.html', len(s), 'bytes')
PY

python3 inject_backnav.py website.html
